function doAction(){if(dialogueOpen){closeDialogue();return}const npc=npcs.find(n=>near(player,n,1.5));if(npc){talk(npc);return}const shard=shardsPos.find(s=>!s.got&&near(player,s,1.25));if(shard){shard.got=true;shards++;updateQuest();notify('Star shard gathered ✦');return}if(near(player,{x:13.7,y:2.2},1.6)){if(shards>=5){ended=true;document.querySelector('#endingBonds').textContent=`${npcs.filter(n=>n.bond>=2).length} companion${npcs.filter(n=>n.bond>=2).length===1?'':'s'} shared a special moment with you.`;document.querySelector('#ending').style.display='grid'}else notify(`The beacon needs ${5-shards} more star shard${5-shards===1?'':'s'}.`);return}notify('Nothing nearby to interact with.')}
